public actor QueryContextUseCase {
    /// Whether the user has explicitly opted in to sending transcript data to MCP providers.
    /// Defaults to `false` — no data leaves the device until the user grants consent.
    public nonisolated let mcpConsentGranted: Bool
    public nonisolated let sensitiveTerms: Set<String>
    private let privacyModeProvider: (any PrivacyModeProvider)?
    /// Updated by the recording session when capture starts/stops.
    public private(set) var isRecording: Bool
    nonisolated private let logger = Logger(subsystem: "app.the-record", category: "QueryContextUseCase")

    /// Updates the recording state so the `.meetings` privacy guard fires correctly.
    /// Call `setRecording(true)` when capture starts and `setRecording(false)` when it ends.
    public func setRecording(_ value: Bool) {
