        self.privacyModeProvider = privacyModeProvider
        self.isRecording = isRecording
        self.sensitiveTerms = sensitiveTerms
    }

    public func query(text: String, providers: [any ContextProvider]) async -> [Suggestion] {
        guard mcpConsentGranted else { return [] }

        // Privacy mode check — read once to avoid re-entrancy (BIZ-006)
        let currentMode = await privacyModeProvider?.currentPrivacyMode ?? .off
        switch currentMode {
        case .always:
            return []
        case .meetings where isRecording:
            return []
        default:
            break
        }

        // Tier filtering: skip providers that don't support the current mode
        let eligibleProviders = providers.filter { $0.supportedPrivacyTiers.contains(currentMode) }

        let sanitizedText = sanitize(text)
        var allResults: [KnowledgeResult] = []

        await withTaskGroup(of: [KnowledgeResult].self) { group in
            for provider in eligibleProviders {
                group.addTask {
                    do {
                        return try await withTimeout(seconds: 5) {
                            try await provider.query(text: sanitizedText)
                        }
                    } catch {
                        self.logger
                            .warning(
                                // swiftlint:disable:next line_length
                                "Provider \(provider.providerID, privacy: .public) failed: \(String(reflecting: error), privacy: .private)"
                            )
                        return []
                    }
                }
            }
            for await results in group {
                allResults.append(contentsOf: results)
            }
        }

        let suggestions = allResults.map { result in
            Suggestion(
                type: .context,
                title: result.title,
                body: result.body,
                sourceProvider: result.providerID,
                deepLinkURL: result.sourceURL,
                relevanceScore: result.relevanceScore
            )
        }

        let deduplicated = deduplicate(suggestions)
        return deduplicated.sorted { $0.relevanceScore > $1.relevanceScore }
    }

    private nonisolated func sanitize(_ text: String) -> String {
        guard !sensitiveTerms.isEmpty else { return text }
        var result = text
        for term in sensitiveTerms where !term.isEmpty {
            result = result.replacingOccurrences(
                of: term,
                with: "[REDACTED]",
                options: [.caseInsensitive]
            )
        }
        return result
    }

    private nonisolated func deduplicate(_ suggestions: [Suggestion]) -> [Suggestion] {
        var seen: [String: Suggestion] = [:]
        for suggestion in suggestions {
            let key = suggestion.title + "||" + suggestion.sourceProvider.rawValue
            if let existing = seen[key] {
                if suggestion.relevanceScore > existing.relevanceScore {
                    seen[key] = suggestion
                }
            } else {
                seen[key] = suggestion
            }
        }
        return Array(seen.values)
    }
}

// MARK: - Typed timeout error

/// Thrown when a context provider exceeds its query time budget.
/// Distinct from `CancellationError` so callers can tell a provider timeout
/// apart from cooperative task cancellation (DPS-4).
private struct ContextProviderTimeoutError: Error {}

// MARK: - withTimeout

/// withTimeout is intentionally duplicated from Infrastructure/Utilities/Timeout.swift.
/// Business cannot import Infrastructure (architecture boundary). Both versions use
/// typed errors (ContextProviderTimeoutError here, TimeoutError there) appropriate
/// to their context. Consolidation would require a shared utility module — not
/// justified for one 10-line function.
private func withTimeout<T: Sendable>(
    seconds: Double,
    operation: @Sendable @escaping () async throws -> T
) async throws -> T {
    try await withThrowingTaskGroup(of: T.self) { group in
        group.addTask { try await operation() }
        group.addTask {
            try await Task.sleep(for: .seconds(seconds))
            throw ContextProviderTimeoutError()
        }
        defer { group.cancelAll() }
        guard let result = try await group.next() else { throw ContextProviderTimeoutError() }
        return result
    }
}

import Domain
import Foundation
import Logging
import OSLog

/// Orchestrates a post-recording cleanup transcription pass.
///
/// After a live recording is complete, this use case loads the stored audio
/// file, runs it through a higher-quality transcription model, and returns a
/// refined ``TranscriptionResult`` with ``TranscriptionPassType/cleanup``.
///
/// All external I/O is delegated to injected domain protocols — this actor
/// contains no direct file-system, audio-framework, or inference dependencies.
public actor CleanupTranscriptionUseCase {
    // MARK: - Dependencies

    private let transcription: any TranscriptionEngine
    private let sampleLoader: any AudioSampleLoader
    private let reader: any RecordingReadRepository
    private let transcriptReader: (any TranscriptReadRepository)?
    private let writer: any TranscriptWriteRepository
    private let telemetry: (any InferenceMetricsRecorder)?

    // MARK: - Logging

    private let logger = Logger(subsystem: "app.the-record", category: "Cleanup")

    // MARK: - Init

    public init(
        transcription: any TranscriptionEngine,
        sampleLoader: any AudioSampleLoader,
        reader: any RecordingReadRepository,
        transcriptReader: (any TranscriptReadRepository)? = nil,
        writer: any TranscriptWriteRepository,
        telemetry: (any InferenceMetricsRecorder)? = nil
    ) {
        self.transcription = transcription
        self.sampleLoader = sampleLoader
        self.reader = reader
        self.transcriptReader = transcriptReader
        self.writer = writer
        self.telemetry = telemetry
    }

    // MARK: - Execute

    /// Runs the cleanup transcription pass for a stored recording.
    ///
    /// - Parameters:
    ///   - recordingId: Unique identifier of the stored recording to transcribe.
    ///   - modelId: Identifier of the higher-quality model to use for
    ///     the cleanup pass (e.g. `"openai_whisper-base.en"`).
    /// - Returns: A ``TranscriptionResult`` with ``TranscriptionPassType/cleanup``
    ///   containing the refined transcript.
    /// - Throws: Any error produced by the storage, sample loader, or
    ///   transcription engine — errors are never swallowed here.
    public func transcribeCleanupPass(
        recordingId: RecordingID,
        modelId: ModelID
    ) async throws -> TranscriptionResult {
        logger
            .info(
                // swiftlint:disable:next line_length
                "Starting cleanup pass for recording \(recordingId, privacy: .private) with model \(modelId, privacy: .public)"
            )

        let signposter = AppLogger.signposter(category: "Performance")
        let signpostState = signposter.beginInterval("Pipeline Cleanup", id: signposter.makeSignpostID())
        defer { signposter.endInterval("Pipeline Cleanup", signpostState) }

        // 1. Retrieve the stored recording.
        let recording = try await reader.getRecording(id: recordingId)
        logger.info("Retrieved recording: \(recording.metadata.id, privacy: .public)")

        // 2. Extract the audio file URL from the recording metadata.
        let audioURL = recording.metadata.audioURL

        // 3. Load PCM samples and the cleanup model in parallel.
        // checkCancellation between the two async let declarations is intentional:
        // structured concurrency will cancel the started `samples` task on scope exit
        // if this throws, so we can safely start both operations.
        async let samples = sampleLoader.loadSamples(from: audioURL)
        try Task.checkCancellation()
        async let modelLoad: Void = transcription.loadModel(modelId)
        let (loadedSamples, _) = try await (samples, modelLoad)
        logger
            .info(
                // swiftlint:disable:next line_length
                "Loaded \(loadedSamples.count, privacy: .public) PCM samples from \(audioURL.lastPathComponent, privacy: .public)"
            )
        logger.info("Model loaded: \(modelId, privacy: .public)")

        // 4. Build the transcription context for a full-file cleanup pass.
        let context = TranscriptionContext(
            modelId: modelId,
            isFinalChunk: true
        )

        // 5. Transcribe — time the inference for result metadata.
        let startTime = CFAbsoluteTimeGetCurrent()
        try Task.checkCancellation()
        let segments = try await transcription.transcribeSegments(samples: loadedSamples, context: context)
        let computeUnit = await transcription.getComputeUnit()
        let elapsed = CFAbsoluteTimeGetCurrent() - startTime

        logger
            .info(
                // swiftlint:disable:next line_length
                "Cleanup transcription complete in \(elapsed, format: .fixed(precision: 3), privacy: .public)s — \(segments.count, privacy: .public) segments"
            )

        // 5b. Record inference telemetry.
        let audioDuration = Double(loadedSamples.count) / 16000.0
        let avgConfidence = segments.isEmpty ? 0.0 : segments.map(\.confidence).reduce(0, +) / Double(segments.count)
        await telemetry?.record(InferenceMetrics(
            modelId: modelId,
            audioDuration: audioDuration,
            inferenceDuration: elapsed,
            realTimeFactor: elapsed > 0 ? audioDuration / elapsed : 0,
            confidence: avgConfidence,
            sampleCount: loadedSamples.count,
            computeUnit: computeUnit,
            timestamp: Date()
        ))

        // 6. Build the TranscriptionResult with passType .cleanup.
        let fullText = segments.map(\.text).joined(separator: " ")
        let result = TranscriptionResult(
            segments: segments,
            fullText: fullText,
            processingTime: elapsed,
            modelId: modelId,
            recordedAt: recording.metadata.recordedAt,
            computeUnit: computeUnit,
            passType: .cleanup
        )

        // 7a. Save draft of the original live transcript before overwriting (idempotent guard, non-fatal).
        // A transient storage failure here must not discard the successfully-computed cleanup result.
        // Skipped when no transcriptReader is injected (can't verify idempotency without it).
        if let transcriptReader {
            do {
                let existingDraft = try await transcriptReader.getTranscriptDraft(for: recordingId)
                if existingDraft == nil, let liveText = recording.transcript?.fullText, !liveText.isEmpty {
                    try await writer.saveDraftTranscript(draftText: liveText, for: recordingId)
                }
            } catch {
                logger.warning("Draft save skipped — non-fatal: \(error, privacy: .public)")
            }
        }

        // 7. Persist the higher-quality cleanup result, overwriting the live pass.
        try await writer.updateTranscript(id: recordingId, transcript: result)
        logger.info("Cleanup transcript persisted for recording \(recordingId, privacy: .public)")

        return result
    }
}

import Domain
import Foundation
import OSLog

/// Orchestrates a post-transcription diarization pass.
///
/// Loads stored audio for a recording, runs it through the diarization engine
/// to identify speaker boundaries, then merges those boundaries with the
/// transcription segments to produce a fully attributed ``DiarizedTranscript``.
///
/// Each ``TranscriptionSegment`` is assigned the speaker whose time range has
/// the maximum overlap with it. Segments that fall entirely outside all speaker
/// ranges are labelled `"Unknown"`.
///
/// All I/O is delegated to injected domain protocols — this actor contains no
/// direct file-system, audio-framework, or inference dependencies.
public actor DiarizeMeetingUseCase {
    // MARK: - Dependencies

    private let diarization: any DiarizationEngine
    private let sampleLoader: any AudioSampleLoader
    private let reader: any RecordingReadRepository
    private let writer: any DiarizationWriteRepository

    // MARK: - Type note
    //
    // `reader` and `writer` are separate narrow-capability protocols
    // (task-007): reads go through `RecordingReadRepository` to fetch the
    // stored recording, writes go through `DiarizationWriteRepository` to
    // persist the merged diarization result.

    // MARK: - Logging

    private let logger = Logger(subsystem: "app.the-record", category: "Diarization")

    // MARK: - Init

    public init(
        diarization: any DiarizationEngine,
        sampleLoader: any AudioSampleLoader,
        reader: any RecordingReadRepository,
        writer: any DiarizationWriteRepository
    ) {
        self.diarization = diarization
        self.sampleLoader = sampleLoader
        self.reader = reader
        self.writer = writer
    }

    // MARK: - Diarize

    /// Produces a diarized transcript by aligning speaker segments with
    /// transcription segments for a stored recording.
    ///
    /// - Parameters:
    ///   - recordingId: Unique identifier of the stored recording.
    ///   - transcription: The transcription result to enrich with speaker labels.
    /// - Returns: A ``DiarizedTranscript`` where every segment carries a speaker
    ///   identity, or `"Unknown"` when no speaker segment overlaps it.
    /// - Throws: Any error produced by storage, sample loader, or diarization —
    ///   errors are never swallowed here.
    // swiftlint:disable:next function_body_length
    public func diarize(
        recordingId: RecordingID,
        transcription: TranscriptionResult
    ) async throws -> DiarizedTranscript {
        logger.info("Starting diarization for recording \(recordingId, privacy: .private)")

        // Step 1: Retrieve the stored recording.
        let recording = try await reader.getRecording(id: recordingId)
        let audioURL = recording.metadata.audioURL
        logger.info("Retrieved recording: \(recording.metadata.id, privacy: .private)")

        // Step 2: Load PCM samples.
        let samples = try await sampleLoader.loadSamples(from: audioURL)
        logger
            .info(
                // swiftlint:disable:next line_length
                "Loaded \(samples.count, privacy: .public) samples from \(audioURL.lastPathComponent, privacy: .public)"
            )

        // Step 3: Gate — prepare the engine if it is not yet ready.
        let ready = await diarization.isReady()
        if !ready {
            try await diarization.prepare()
        }

        // Step 3 (continued): Run diarization.
        let startTime = CFAbsoluteTimeGetCurrent()
        let speakerSegments = try await diarization.diarize(samples: samples, sampleRate: 16000)
        logger.info("Diarization engine returned \(speakerSegments.count, privacy: .public) speaker segments")
        for (i, seg) in speakerSegments.prefix(10).enumerated() {
            logger
                .info(
                    // swiftlint:disable:next line_length
                    "  speaker[\(i, privacy: .public)]: id=\(seg.speakerId, privacy: .public) start=\(seg.startTime, format: .fixed(precision: 1), privacy: .public)s end=\(seg.endTime, format: .fixed(precision: 1), privacy: .public)s"
                )
        }

        // Step 4: Merge speaker segments with transcription segments by max overlap.
        logger
            .info(
                // swiftlint:disable:next line_length
                "Merging \(speakerSegments.count, privacy: .public) speaker segments × \(transcription.segments.count, privacy: .public) transcription segments"
            )
        for (i, seg) in transcription.segments.prefix(5).enumerated() {
            logger
                .info(
                    // swiftlint:disable:next line_length
                    "  transcript[\(i, privacy: .public)]: start=\(seg.startTime, format: .fixed(precision: 1), privacy: .public)s end=\(seg.endTime, format: .fixed(precision: 1), privacy: .public)s text=\(String(seg.text.prefix(40)), privacy: .private)"
                )
        }
        // Compute each overlap once per (speaker, transcript) pair — previous code called
        // overlapDuration 3× per transcript segment (2× in max(by:) + 1× to check > 0).
        let diarizedSegments: [DiarizedSegment] = transcription.segments.map { seg in
            let best = speakerSegments
                .map { (speaker: $0, overlap: overlapDuration($0, seg)) }
                .max(by: { $0.overlap < $1.overlap })
            let speakerId: SpeakerID = if let b = best, b.overlap > 0 {
                b.speaker.speakerId
            } else {
                SpeakerID.unknown
            }
            return DiarizedSegment(
                text: seg.text,
                speakerId: speakerId,
                startTime: seg.startTime,
                endTime: seg.endTime,
                confidence: seg.confidence
            )
        }

        let elapsed = CFAbsoluteTimeGetCurrent() - startTime

        // Step 5: Unique speaker count from diarization output.
        let uniqueSpeakers = Set(speakerSegments.map(\.speakerId))
        let count = diarizedSegments.count
        let speakerCount = uniqueSpeakers.count
        logger
            .info(
                // swiftlint:disable:next line_length
                "Merged \(count, privacy: .public) segments across \(speakerCount, privacy: .public) speakers in \(elapsed, format: .fixed(precision: 3), privacy: .public)s"
            )

        let diarizedTranscript = DiarizedTranscript(
            segments: diarizedSegments,
            speakerCount: uniqueSpeakers.count,
            processingTime: elapsed
        )

        // Step 6: Persist the diarization result so speaker labels survive app restart.
        try await writer.attachDiarization(id: recordingId, diarization: diarizedTranscript)
        logger.info("Diarization persisted for recording \(recordingId, privacy: .private)")

        return diarizedTranscript
    }

    // MARK: - Helpers

    private nonisolated func overlapDuration(
        _ speaker: SpeakerSegment,
        _ transcript: TranscriptionSegment
    ) -> TimeInterval {
        max(0, min(speaker.endTime, transcript.endTime) - max(speaker.startTime, transcript.startTime))
    }
}

import Domain
import Foundation
import OSLog

/// Use case that initiates a new audio recording session.
///
/// Validates that no recording is already in progress, delegates capture to the
/// injected ``AudioCaptureEngine``, creates a ``RecordingSession`` value, and
/// returns it to the caller. The session is also retained internally so other
/// actors can query the active session via ``getCurrentSession()``.
///
/// ## Concurrency safety
///
/// A use-case-level state machine (`State`) reserves the recording slot
/// **synchronously** — before any `await` — eliminating the check-then-act race
/// that existed when the guard relied on `await audioCapture.isRecording()`.
/// Two concurrent `start()` calls cannot both proceed past the `.idle` guard
/// because the actor serialises synchronous access: the first call transitions
/// to `.starting` before it suspends, so the second call sees a non-idle state
/// and throws immediately.
///
/// ## Usage
/// ```swift
/// let useCase = StartRecordingUseCase(
///     audioCapture: captureEngine,
///     storage: storageEngine
/// )
/// let session = try await useCase.start()
/// // … later, when the recording is stopped …
/// await useCase.sessionDidEnd()
/// ```
public actor StartRecordingUseCase {
    // MARK: - State machine

    private enum State {
        /// No recording in progress; ready to accept a new session.
        case idle
        /// `start()` has reserved the slot and is awaiting the capture engine.
        case starting
        /// Capture is running and a session is live.
        case recording
    }

    // MARK: - Dependencies

    private let audioCapture: any AudioCaptureEngine
    private let storage: any RecordingWriteRepository
    private let micCapture: (any MicCaptureEngine)?
    private let queryContext: QueryContextUseCase?

    // MARK: - State

    private var state: State = .idle
    private var currentSession: RecordingSession?
    private var activeBufferStream: AudioBufferStream?
    private var activeMicStream: AsyncThrowingStream<TaggedAudioBuffer, Error>?

    // MARK: - Logging

    private let logger = Logger(subsystem: "app.the-record", category: "StartRecording")

    // MARK: - Initialiser

    /// Creates a ``StartRecordingUseCase`` with its required dependencies.
    ///
    /// - Parameters:
    ///   - audioCapture: The audio capture backend to start and query.
    ///   - storage: The persistence backend for recorded audio files.
    ///   - micCapture: Optional microphone capture engine. When provided, the use case
    ///     starts both system and microphone capture. When `nil` or when mic start fails,
    ///     only system audio is captured and ``getMicStream()`` returns `nil`.
    public init(
        audioCapture: any AudioCaptureEngine,
        storage: any RecordingWriteRepository,
        micCapture: (any MicCaptureEngine)? = nil,
        queryContext: QueryContextUseCase? = nil
    ) {
        self.audioCapture = audioCapture
        self.storage = storage
        self.micCapture = micCapture
        self.queryContext = queryContext
    }

    // MARK: - Start

    /// Starts a new recording session.
    ///
    /// 1. Atomically reserves the recording slot (`.idle → .starting`) before
    ///    any `await`, preventing concurrent callers from both proceeding.
    /// 2. Starts the capture engine with a default ``AudioConfiguration``.
    /// 3. Constructs and stores a ``RecordingSession`` (`.starting → .recording`).
    /// 4. Returns the session to the caller.
    ///
    /// On any failure the state is rolled back to `.idle` so a subsequent call
    /// can succeed.
    ///
    /// - Returns: A ``RecordingSession`` representing the newly started session.
    /// - Throws: ``RecordingError/alreadyRecording`` if a session is already
    ///   active (state is `.starting` or `.recording`), or any error propagated
    ///   from the audio capture engine.
    public func start() async throws -> RecordingSession {
        // ── Atomic reservation (no await yet) ────────────────────────────────
        // Actor isolation guarantees this guard + assignment is never interleaved
        // with another start() call.  The first caller wins; subsequent callers
        // see a non-idle state and throw before touching any async code.
        guard state == .idle else {
            logger
                .warning("Start requested while state=\(String(describing: self.state), privacy: .public) — rejecting")
            throw RecordingError.alreadyRecording
        }
        state = .starting // ← reservation committed before the first await

        // ── Async work (actor may suspend here) ──────────────────────────────
        // Capture T0 before starting either actor so both streams share the same epoch.
        let sessionStartTick = mach_absolute_time()
        var config = AudioConfiguration()
        config.sessionStartTick = sessionStartTick
        let sessionID = RecordingID.generate()
        do {
            try Task.checkCancellation()
            let bufferStream = try await audioCapture.start(sessionID: sessionID, configuration: config)
            activeBufferStream = bufferStream
            logger.info("Audio capture started — stream id: \(bufferStream.id, privacy: .public)")

            // ── Optional mic capture ───────────────────────────────────────────
            if let mic = micCapture {
                // Mic failure is no longer swallowed (Epic #343). We propagate the
                // error so the UI can alert the user rather than silently recording
                // system-audio only when they expected both tracks.
                let micStream = try await mic.start(sessionStartTick: sessionStartTick)
                activeMicStream = micStream
                logger.info("Mic capture started — dual-track stream active")
            }

            let session = RecordingSession(
                id: sessionID,
                startedAt: Date(),
                configuration: config
            )

            // Persist stub immediately so a crash mid-recording leaves a recoverable row (#161).
            try await storage.markSessionStarted(id: session.id, startedAt: session.startedAt)
            state = .recording
            currentSession = session
            await queryContext?.setRecording(true)
            logger.info("Recording session started: \(session.id, privacy: .public)")
            return session
        } catch {
            // Roll back so the next start() attempt can proceed.
            state = .idle
            // If audio capture was already started before the failure/cancellation,
            // stop it to release the HAL tap and WAVWriter (Concern #4).
            if activeBufferStream != nil {
                do { _ = try await audioCapture.stop() } catch {
                    logger
                        .warning(
                            "Audio capture stop failed during rollback: \(String(reflecting: error), privacy: .private)"
                        )
                }
                activeBufferStream = nil
            }
            if let mic = micCapture, activeMicStream != nil {
                do { try await mic.stop() } catch {
                    logger
                        .warning(
                            "Mic capture stop failed during rollback: \(String(reflecting: error), privacy: .private)"
                        )
                }
                activeMicStream = nil
            }
            logger
                .error("Failed to start capture — state reset to idle: \(String(reflecting: error), privacy: .public)")
            throw error
        }
    }

    // MARK: - Session End

    /// Marks the current recording as ended and resets state to `.idle`.
    ///
    /// Call this from the stop use case (or coordinator) after the audio capture
    /// has been stopped and the session data has been persisted.  Failing to call
    /// this leaves the state machine in `.recording`, blocking any future
    /// `start()` call.
    ///
    /// If a microphone capture engine was provided, its `stop()` is called here.
    /// Any error from mic stop is swallowed — the session end is unconditional.
    public func sessionDidEnd() async {
        logger
            .info(
                "Recording session ended — resetting to idle (was \(String(describing: self.state), privacy: .public))"
            )
        do {
            try await micCapture?.stop()
        } catch {
            logger.warning(
                "Mic stop failed during sessionDidEnd (swallowed): \(String(reflecting: error), privacy: .private)"
            )
        }
        state = .idle
        currentSession = nil
        activeBufferStream = nil
        activeMicStream = nil
        await queryContext?.setRecording(false)
    }

    /// Returns the system audio stream when capture is active, or `nil` otherwise.
    public func getSystemStream() -> AudioBufferStream? {
        activeBufferStream
    }

    /// Returns the raw microphone stream when dual-track capture is active.
    ///
    /// Returns `nil` when no `micCapture` was provided, or when mic `start()` failed.
    public func getMicStream() -> AsyncThrowingStream<TaggedAudioBuffer, Error>? {
        activeMicStream
    }

    // MARK: - Session Query

    /// Returns the current recording session, or `nil` when no session is active.
    public func getCurrentSession() -> RecordingSession? {
        currentSession
    }

    /// Returns the active session's ID, or `nil` when no recording is in progress.
    public func activeSessionId() -> RecordingID? {
        currentSession?.id
    }
}

