    func saveRecording(_ file: AudioFile) async throws -> StoredRecording
    func deleteRecording(id: RecordingID) async throws
    /// Persists a recoverable stub row the moment capture starts (#161, #323).
    ///
    /// - Parameters:
    ///   - id: The stable identifier shared with the eventual ``AudioFile``.
    ///   - startedAt: Wall-clock time the session began.
    ///   - audioURL: The on-disk WAV location capture is writing to. Recorded so a
    ///     crash-mid-recording can be recovered on next launch — without it the
    ///     pending row has no link back to the file on disk.
    func markSessionStarted(id: RecordingID, startedAt: Date, audioURL: URL) async throws
    /// Attaches the AEC-cleaned microphone WAV path to an existing recording row.
    /// A no-op when `path` is nil. Idempotent — safe to call more than once (IDEM-002).
    func updateCleanedMicPath(id: RecordingID, path: URL?) async throws
    /// Marks a stored recording as needing re-transcription after a WhisperKit/MLX crash (#116).
    ///
    /// Called by `StopAndTranscribeUseCase` when transcription fails after the audio was already
    /// saved to storage. The WAV at `audioURL` is retained on disk so the session can be retried
    /// on next app launch via `RecoverPendingSessionsUseCase`.
    ///
    /// - Parameters:
    ///   - id: The stable identifier of the recording to mark.
    ///   - audioURL: The on-disk URL of the preserved WAV file.
    func markNeedsRetranscription(id: RecordingID, audioURL: URL) async throws
    /// Clears the needs-retranscription flag after a retry succeeds (#326).
    ///
    /// Without this, `markNeedsRetranscription` is a one-way door: a single
    /// transcription failure would mean the recording is picked up by
    /// `RecoverPendingSessionsUseCase` and re-transcribed at every launch forever.
    /// Call this ONLY after the retried transcript has been persisted successfully —
    /// if the retry fails again, the flag must stay set so the session is retried
    /// on the next launch too (bounded-retry backoff is out of scope for #326).
    ///
    /// - Parameter id: The identifier of the recording whose flag should be cleared.
    func clearNeedsRetranscription(id: RecordingID) async throws
    func importMetadata(_ metadata: RecordingMetadata) async throws
}

