import Foundation

/// Capability protocol for persisting and mutating audio recording metadata.
///
/// Consumed by call sites that create, remove, or track the lifecycle of
/// recordings and should not be granted read/list access to storage.
public protocol RecordingWriteRepository: Sendable {
    /// Persists an audio file and its associated metadata.
    ///
    /// - Parameter file: The completed audio file to store, including its on-disk URL and capture metadata.
    /// - Returns: A ``StoredRecording`` representing the newly persisted record.
    /// - Throws: A storage error if the underlying persistence layer fails to write the record.
    func saveRecording(_ file: AudioFile) async throws -> StoredRecording

    /// Removes the recording with the given identifier.
    ///
    /// This operation is **not** idempotent — attempting to delete a recording that
    /// does not exist throws ``RecordingNotFoundError`` rather than succeeding silently.
    /// - Parameter id: The stable, opaque identifier of the recording to delete.
    /// - Throws: ``RecordingNotFoundError`` if no recording exists for `id`;
    ///   a storage error for any other persistence failure.
    func deleteRecording(id: RecordingID) async throws

    /// Persists a pending session stub at recording start so a crash mid-recording
    /// leaves a recoverable row in storage (#161).
    ///
    /// Called by `StartRecordingUseCase` immediately after audio capture begins.
    /// The stub uses placeholder values for fields that aren't known until stop().
    /// Calling `saveRecording(_:)` with the same ID later overwrites the stub.
    ///
    /// - Parameters:
    ///   - id: The session ID, matching the `RecordingSession.id` created by the use case.
    ///   - startedAt: Wall-clock time when recording began.
    /// - Throws: A storage error if the underlying persistence layer fails.
    func markSessionStarted(id: RecordingID, startedAt: Date) async throws

    /// Marks a recording as needing re-transcription after a transcription
    /// crash, preserving the captured audio so it can be recovered later.
    ///
    /// Called by `StopAndTranscribeUseCase` when transcription fails but the
    /// audio file on disk is non-empty. `listNeedsRetranscription()` on the
    /// read side surfaces these rows for crash recovery.
    ///
    /// - Parameters:
    ///   - id: The session ID of the recording whose transcription failed.
    ///   - audioURL: On-disk URL of the preserved audio file.
    /// - Throws: A storage error if the underlying persistence layer fails.
    func markNeedsRetranscription(id: RecordingID, audioURL: URL) async throws
}

