import Foundation

/// Capability protocol for persisting and retrieving audio recording metadata.
///
/// Consumed by the recording, transcription, and summarization use cases that need
/// to store or look up meeting recordings. The canonical conforming type is
/// the persistent storage backend.
///
/// This protocol is composed from ``RecordingReadRepository`` and
/// ``RecordingWriteRepository`` so that callers needing only one capability
/// can depend on the narrower protocol instead of the full surface.
public typealias RecordingRepository = RecordingReadRepository & RecordingWriteRepository

import Foundation
@testable import Business
import Domain
import Testing

// MARK: - Fakes

/// Fake read-side repository conforming to ``RecordingReadRepository`` so tests
/// can drive `AutoCleanupUseCase.cleanup(policy:now:)` without a real storage
/// backend. Records whether `totalStorageSize()` was invoked so tests can
/// assert the read-only listing/sizing path was actually exercised.
private actor FakeRecordingReadRepository: RecordingReadRepository {
    var mockRecordings: [RecordingSummary] = []
    var mockTotalSize: Int64 = 0
    private(set) var totalStorageSizeCallCount = 0
    private(set) var listRecordingsCallCount = 0

    func setMockRecordings(_ recordings: [RecordingSummary]) {
        mockRecordings = recordings
    }

    func setMockTotalSize(_ size: Int64) {
        mockTotalSize = size
    }

    func getRecording(id: RecordingID) async throws -> StoredRecording {
        throw StorageError.recordingNotFound(id: id)
    }

    func listRecordings(limit _: Int?, offset _: Int?) async throws -> [RecordingSummary] {
        listRecordingsCallCount += 1
        return mockRecordings
    }

    func totalStorageSize() async throws -> Int64 {
        totalStorageSizeCallCount += 1
        return mockTotalSize
    }

    func listPendingSessions() async throws -> [RecordingID] { [] }

    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] { [] }

    func listNeedsRetranscription() async throws -> [RecordingID] { [] }
}

/// Fake write-side repository conforming to ``RecordingWriteRepository`` that
/// records every `deleteRecording(id:)` call so tests can assert exactly which
/// stale recordings the use case deleted.
private actor FakeRecordingWriteRepository: RecordingWriteRepository {
    private(set) var deletedIDs: [RecordingID] = []
    private(set) var deleteRecordingCallCount = 0

    func saveRecording(_ file: AudioFile) async throws -> StoredRecording {
        StoredRecording(
            metadata: RecordingMetadata(
                id: file.id,
                recordedAt: file.recordedAt,
                duration: file.duration,
                fileSize: file.fileSize,
                audioURL: file.url,
                transcriptURL: nil,
                modelId: ModelID("fake-model"),
                processingTime: 0,
                computeUnit: .cpuOnly,
                wordCount: 0
            )
        )
    }

    func deleteRecording(id: RecordingID) async throws {
        deleteRecordingCallCount += 1
        deletedIDs.append(id)
    }

    func markSessionStarted(id _: RecordingID, startedAt _: Date) async throws {}

    func updateCleanedMicPath(id _: RecordingID, path _: URL?) async throws {}

    func markNeedsRetranscription(id _: RecordingID, audioURL _: URL) async throws {}

    func importMetadata(_: RecordingMetadata) async throws {}
}

// MARK: - Helpers

private func makeSummary(
    id: String,
    daysAgo: Double,
    now: Date
) -> RecordingSummary {
    RecordingSummary(
        id: RecordingID(id),
        date: now.addingTimeInterval(-daysAgo * 86400),
        duration: 60.0,
        wordCount: 100
    )
}

// MARK: - Suite

@Suite("AutoCleanupUseCase — split Read/Write repository protocols")
struct AutoCleanupUseCaseTests {
    let now = Date()

    // AC1: AutoCleanupUseCase.swift:24 (`reader: any RecordingReadRepository`)
    // and :25 (`writer: any RecordingWriteRepository`) — the use case must
    // compile and construct against two distinct protocol-typed dependencies,
    // not a single combined RecordingRepository.
    @Test("AutoCleanupUseCase initializes with distinct read and write repository fakes")
    func initializesWithDistinctReadAndWriteRepositories() async throws {
        let reader = FakeRecordingReadRepository()
        let writer = FakeRecordingWriteRepository()
        await reader.setMockRecordings([])
        await reader.setMockTotalSize(0)

        let useCase = AutoCleanupUseCase(reader: reader, writer: writer)
        let policy = try CleanupPolicy(retentionDays: 90, folderSizeWarningGB: 5.0)
        let result = try await useCase.cleanup(policy: policy, now: now)

        #expect(result.deletedCount == 0, "with no recordings, cleanup must report zero deletions")
        let readCalls = await reader.listRecordingsCallCount
        #expect(readCalls == 1, "cleanup must list recordings exactly once via the read repository")
    }

    // AC2: cleanup behavior (list stale recordings via the reader, then delete
    // them via the writer) must be unchanged versus the App-side reference
    // implementation at Record-App/Sources/Business/UseCases/AutoCleanupUseCase.swift —
    // recordings older than the retention window are deleted; recent ones are kept.
    @Test("cleanup deletes only recordings older than the retention window")
    func cleanupDeletesOnlyStaleRecordings() async throws {
        let reader = FakeRecordingReadRepository()
        let writer = FakeRecordingWriteRepository()
        let old = makeSummary(id: "old", daysAgo: 200, now: now)
        let recent = makeSummary(id: "recent", daysAgo: 10, now: now)
        await reader.setMockRecordings([old, recent])
        await reader.setMockTotalSize(0)

        let useCase = AutoCleanupUseCase(reader: reader, writer: writer)
        let policy = try CleanupPolicy(retentionDays: 90, folderSizeWarningGB: 5.0)
        let result = try await useCase.cleanup(policy: policy, now: now)

        #expect(result.deletedCount == 1, "exactly one recording (the 200-day-old one) must be deleted")
        let deletedIDs = await writer.deletedIDs
        #expect(
            deletedIDs == [RecordingID("old")],
            "the write repository must receive a delete call for the stale recording's exact id, and no other"
        )
    }

    // AC3: AutoCleanupUseCaseTests must exercise both the read-only listing
    // path (recent recordings surfaced by the reader but never deleted) and
    // the write-based deletion path (the writer's deleteRecording is invoked
    // only for stale ids, and totalStorageSize is consulted for the folder
    // size warning).
    @Test("recent recordings are surfaced by the read path but never reach the write-based deletion path")
    func recentRecordingsAreListedButNotDeleted() async throws {
        let reader = FakeRecordingReadRepository()
        let writer = FakeRecordingWriteRepository()
        let recent = makeSummary(id: "recent-only", daysAgo: 1, now: now)
        await reader.setMockRecordings([recent])
        await reader.setMockTotalSize(2 * 1_073_741_824)

        let useCase = AutoCleanupUseCase(reader: reader, writer: writer)
        let policy = try CleanupPolicy(retentionDays: 90, folderSizeWarningGB: 5.0)
        let result = try await useCase.cleanup(policy: policy, now: now)

        #expect(result.deletedCount == 0, "a recording within the retention window must not be deleted")
        let deleteCallCount = await writer.deleteRecordingCallCount
        #expect(deleteCallCount == 0, "the write repository's deleteRecording must never be called for recent recordings")
        let sizeCalls = await reader.totalStorageSizeCallCount
        #expect(sizeCalls == 1, "the read repository's totalStorageSize must be consulted to compute the folder warning")
    }
}

import Foundation
@testable import Business
import Domain
import Testing

// MARK: - Fakes

/// Fake ``AudioCaptureEngine`` that records the exact `sessionID` and
/// `configuration` it was invoked with so tests can assert on them without a
/// real CoreAudio/AVFoundation backend.
private actor FakeAudioCaptureEngine: AudioCaptureEngine {
    private(set) var startCallCount = 0
    private(set) var lastSessionID: RecordingID?
    private(set) var lastConfiguration: AudioConfiguration?
    private var recording = false

    func start(sessionID: RecordingID, configuration: AudioConfiguration) async throws -> AudioBufferStream {
        startCallCount += 1
        lastSessionID = sessionID
        lastConfiguration = configuration
        recording = true
        return AudioBufferStream(
            id: sessionID,
            stream: AsyncStream { continuation in continuation.finish() },
            fileURL: URL(fileURLWithPath: "/tmp/fake-\(sessionID.rawValue).wav"),
            configuration: configuration
        )
    }

    func stop() async throws -> AudioFile {
        recording = false
        return AudioFile(
            id: lastSessionID ?? .generate(),
            url: URL(fileURLWithPath: "/tmp/fake-stopped.wav"),
            recordedAt: Date(timeIntervalSince1970: 0),
            duration: 0,
            fileSize: 0,
            configuration: lastConfiguration ?? AudioConfiguration(),
            sampleCount: 0
        )
    }

    func isRecording() async -> Bool {
        recording
    }
}

/// Fake write-side repository that records every `markSessionStarted` call so
/// tests can assert the use case persisted a pending-session stub without a
/// real storage backend.
private actor FakeRecordingWriteRepository: RecordingWriteRepository {
    private(set) var markSessionStartedCalls: [(id: RecordingID, startedAt: Date)] = []

    func saveRecording(_ file: AudioFile) async throws -> StoredRecording {
        StoredRecording(
            metadata: RecordingMetadata(
                id: file.id,
                recordedAt: file.recordedAt,
                duration: file.duration,
                fileSize: file.fileSize,
                audioURL: file.url,
                transcriptURL: nil,
                modelId: ModelID("fake-model"),
                processingTime: 0,
                computeUnit: .cpuOnly,
                wordCount: 0
            )
        )
    }

    func deleteRecording(id _: RecordingID) async throws {}

    func markSessionStarted(id: RecordingID, startedAt: Date) async throws {
        markSessionStartedCalls.append((id: id, startedAt: startedAt))
    }

    func updateCleanedMicPath(id _: RecordingID, path _: URL?) async throws {}

    func markNeedsRetranscription(id _: RecordingID, audioURL _: URL) async throws {}

    func importMetadata(_: RecordingMetadata) async throws {}
}

// MARK: - Suite

@Suite("StartRecordingUseCase — AudioCaptureEngine.start(sessionID:configuration:)")
struct StartRecordingUseCaseTests {
    // AC1: StartRecordingUseCase.swift:120 calls
    // audioCapture.start(sessionID: <RecordingID>, configuration: config)
    @Test("start() invokes audioCapture.start with a non-nil sessionID and the built configuration")
    func startPassesSessionIDToAudioCaptureEngine() async throws {
        let fakeCapture = FakeAudioCaptureEngine()
        let fakeStorage = FakeRecordingWriteRepository()
        let useCase = StartRecordingUseCase(audioCapture: fakeCapture, storage: fakeStorage)

        _ = try await useCase.start()

        let callCount = await fakeCapture.startCallCount
        let sessionID = await fakeCapture.lastSessionID
        #expect(callCount == 1, "audioCapture.start must be invoked exactly once per start() call")
        #expect(sessionID != nil, "audioCapture.start must receive a non-nil sessionID argument")
    }

    // AC2: The sessionID passed matches the RecordingID generated/used for the
    // current recording session.
    @Test("the sessionID passed to audioCapture.start equals the returned RecordingSession's id")
    func sessionIDMatchesReturnedSessionID() async throws {
        let fakeCapture = FakeAudioCaptureEngine()
        let fakeStorage = FakeRecordingWriteRepository()
        let useCase = StartRecordingUseCase(audioCapture: fakeCapture, storage: fakeStorage)

        let session = try await useCase.start()

        let sessionID = await fakeCapture.lastSessionID
        #expect(
            sessionID == session.id,
            "the sessionID handed to the capture engine must be the exact RecordingID of the session returned to the caller"
        )
    }

    // AC3: StartRecordingUseCase compiles against
    // AudioCaptureEngine.start(sessionID:configuration:) with no signature mismatch.
    @Test("StartRecordingUseCase's audioCapture dependency satisfies the two-argument start(sessionID:configuration:) signature")
    func useCaseCompilesAgainstTwoArgumentStartSignature() async throws {
        let fakeCapture = FakeAudioCaptureEngine()
        let fakeStorage = FakeRecordingWriteRepository()
        let useCase = StartRecordingUseCase(audioCapture: fakeCapture, storage: fakeStorage)

        let session = try await useCase.start()

        let lastConfiguration = await fakeCapture.lastConfiguration
        #expect(
            lastConfiguration == session.configuration,
            "the configuration argument threaded through start(sessionID:configuration:) must match the session's configuration"
        )
    }

    // AC4: StartRecordingUseCaseTests verifies a fake AudioCaptureEngine
    // receives the expected sessionID.
    @Test("a second concurrent-looking start() call after a completed session issues a fresh, different sessionID")
    func distinctStartCallsReceiveDistinctSessionIDs() async throws {
        let fakeCapture = FakeAudioCaptureEngine()
        let fakeStorage = FakeRecordingWriteRepository()
        let useCase = StartRecordingUseCase(audioCapture: fakeCapture, storage: fakeStorage)

        let firstSession = try await useCase.start()
        let firstSeenSessionID = await fakeCapture.lastSessionID
        #expect(
            firstSeenSessionID == firstSession.id,
            "fake AudioCaptureEngine must observe exactly the sessionID of the first session"
        )

        await useCase.sessionDidEnd()
        let secondSession = try await useCase.start()
        let secondSeenSessionID = await fakeCapture.lastSessionID

        #expect(
            secondSeenSessionID == secondSession.id,
            "fake AudioCaptureEngine must observe the sessionID of the second, distinct session"
        )
        #expect(
            secondSession.id != firstSession.id,
            "each start() call must generate a new, distinct RecordingID"
        )
    }
}

