    ///   a storage error for any other persistence failure.
    func getRecording(id: RecordingID) async throws -> StoredRecording

    /// Returns all recordings, sorted by creation date descending (newest first).
    ///
    /// An empty array signals that no recordings exist; this method does not throw
    /// to indicate an empty collection.
    /// - Returns: An array of ``RecordingSummary`` values ordered newest-first,
    ///   or an empty array if no recordings have been saved.
    /// - Throws: A storage error if the underlying persistence layer cannot be queried.
    func listRecordings(limit: Int?, offset: Int?) async throws -> [RecordingSummary]

    /// Returns the total disk space consumed by all stored recordings, in bytes.
    ///
    /// Counts only audio files tracked by this repository; temporary files and
    /// WAV debug dumps are excluded.
    /// - Returns: The aggregate file size in bytes (`Int64`).
    /// - Throws: A storage error if the size cannot be computed.
    func totalStorageSize() async throws -> Int64

    /// Returns the IDs of all sessions that were started but never completed (#161 recovery flow).
    ///
    /// A pending session is one where `markSessionStarted(id:startedAt:)` was called
    /// but `saveRecording(_:)` was never called (e.g. the app crashed mid-recording).
    /// Called once at app launch to surface crash-recovery candidates to the user.
    ///
    /// - Returns: An array of ``RecordingID`` values for incomplete sessions, oldest-first.
    /// - Throws: A storage error if the underlying persistence layer cannot be queried.
    func listPendingSessions() async throws -> [RecordingID]

    /// Returns full metadata for all recordings in a single storage call, sorted
    /// newest-first.
    ///
    /// Prefer this over listRecordings() + N x getRecording(id:) when the caller
    /// needs the complete RecordingMetadata for every recording. One round-trip
    /// to the persistence layer replaces N+1 serial calls.
    ///
    /// - Returns: An array of RecordingMetadata ordered newest-first.
    /// - Throws: A storage error if the underlying persistence layer cannot be queried.
    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata]

    /// Returns IDs of recordings whose transcription failed and need a retry (#116).
    ///
    /// A recording enters this state when `markNeedsRetranscription(id:audioURL:)` was
    /// called by `StopAndTranscribeUseCase` after a WhisperKit/MLX crash, and has not
    /// yet been successfully re-transcribed.
    ///
    /// - Returns: An array of ``RecordingID`` values for crash-recoverable sessions, oldest-first.
    /// - Throws: A storage error if the underlying persistence layer cannot be queried.
    func listNeedsRetranscription() async throws -> [RecordingID]

    /// Fetches a recording by ID for crash recovery, including rows still marked
    /// `is_pending` (#323).
    ///
    /// `getRecording(id:)` deliberately excludes pending rows so normal list/detail
    /// flows never surface an in-progress or crashed session. Recovery needs the
    /// opposite: it must be able to read the stub row `markSessionStarted` wrote so
    /// it can re-transcribe the on-disk WAV and finish the session. Use this method
    /// ONLY from recovery flows (``getRecording(id:)`` remains the default for
    /// everything else).
    ///
    /// - Parameter id: The identifier of the recording to recover.
    /// - Returns: The ``StoredRecording``, pending or not.
    /// - Throws: A storage error if no row exists at all.
    func getRecordingForRecovery(id: RecordingID) async throws -> StoredRecording
}

public extension RecordingReadRepository {
    /// Convenience overload: full unbounded listing (protocols cannot declare default arguments).
    func listRecordings() async throws -> [RecordingSummary] {
        try await listRecordings(limit: nil, offset: nil)
    }
}

import Foundation
import OSLog
import Domain

/// Checks for recording sessions that were started but never completed (#161).
///
/// Called once at app launch. A session is pending when `markSessionStarted`
/// ran (e.g. capture began) but `saveRecording` never followed — typically
/// because the app crashed mid-recording.
///
/// Returns the pending IDs. The caller (AppAssembler) feeds each ID into
/// `MenuBarViewModel.recoverPendingSession` for re-transcription and pipeline.
public actor RecoverPendingSessionsUseCase {

    private let storage: any RecordingReadRepository
    private let logger = Logger(subsystem: "app.the-record", category: "Recovery")

    public init(storage: some RecordingReadRepository) {
        self.storage = storage
    }

    /// Returns the IDs of all pending sessions and logs a summary.
    ///
    /// Combines two classes of recoverable sessions:
    /// - Crash-mid-capture: `listPendingSessions()` (audio was never saved)
    /// - Crash-mid-transcription: `listNeedsRetranscription()` (#116) (audio saved, transcription crashed)
    ///
    /// - Returns: Deduplicated `RecordingID` values. Empty if none.
    @discardableResult
    public func callAsFunction() async throws -> [RecordingID] {
        let pendingIDs = try await storage.listPendingSessions()
        let needsRetranscriptionIDs = try await storage.listNeedsRetranscription()
        // Deduplicate while preserving order: pending first, then needsRetranscription.
        let ids = (pendingIDs + needsRetranscriptionIDs).reduce(into: (seen: Set<RecordingID>(), list: [RecordingID]())) { acc, id in
            guard acc.seen.insert(id).inserted else { return }
            acc.list.append(id)
        }.list
        if ids.isEmpty {
            logger.info("Recovery check: no pending sessions found")
        } else {
            logger.warning(
                // swiftlint:disable:next line_length
                "Recovery check: \(ids.count, privacy: .public) pending session(s) found — re-transcribing. IDs: \(ids.map(\.rawValue).joined(separator: ", "), privacy: .private)",
            )
        }
        return ids
    }
}

