private actor FakeAudioCaptureEngine: AudioCaptureEngine {
    private(set) var startCallCount = 0
    private(set) var lastSessionID: RecordingID?
    private(set) var lastConfiguration: AudioConfiguration?
    private var recording = false

    func start(sessionID: RecordingID, configuration: AudioConfiguration) async throws -> AudioBufferStream {
        startCallCount += 1
        lastSessionID = sessionID
        lastConfiguration = configuration
        recording = true
        return AudioBufferStream(
            id: sessionID,
            stream: AsyncStream { continuation in continuation.finish() },
            fileURL: URL(fileURLWithPath: "/tmp/fake-\(sessionID.rawValue).wav"),
            configuration: configuration
        )
