import Foundation

// MARK: - TimeoutError

/// Thrown when an async operation exceeds its allowed duration.
public struct TimeoutError: Error, Sendable {
    public init() {}
}

// MARK: - withTimeout

/// Executes `operation` with a deadline of `duration`.
///
/// Returns the operation's result if it completes before the deadline.
/// Throws ``TimeoutError`` if the deadline elapses first.
/// Any error thrown by `operation` propagates directly without wrapping.
///
/// Implementation: two child tasks race inside a `withThrowingTaskGroup`.
/// The first task to finish wins; `group.cancelAll()` terminates the loser.
///
/// - Parameters:
///   - duration: Maximum time allowed for `operation` to complete.
///   - operation: The async work to perform.
/// - Returns: The value produced by `operation`.
/// - Throws: ``TimeoutError`` if `duration` elapses, or any error thrown by `operation`.
public func withTimeout<T: Sendable>(
    _ duration: Duration,
    operation: @Sendable @escaping () async throws -> T
) async throws -> T {
    try await withThrowingTaskGroup(of: TimeoutOutcome<T>.self) { group in
        // Task 1 — the real work.
        group.addTask {
            let value = try await operation()
            return .value(value)
        }

        // Task 2 — the deadline sentinel.
        group.addTask {
            try await Task.sleep(for: duration)
            return .timedOut
        }

        // Wait for whichever task finishes first.
        // If the operation task throws, `group.next()` rethrows that error
        // and the group's implicit cleanup cancels the sentinel task.
        guard let outcome = try await group.next() else {
            // Unreachable: we always add exactly two tasks above.
            group.cancelAll()
            throw TimeoutError()
        }

        // Cancel the losing task.
        group.cancelAll()

        switch outcome {
        case let .value(result):
            return result
        case .timedOut:
            throw TimeoutError()
        }
    }
}

// MARK: - Private Support Types

/// Discriminated union used as the child-task result type.
/// Kept private — callers only see `T` or `TimeoutError`.
private enum TimeoutOutcome<T: Sendable> {
    case value(T)
    case timedOut
}

