import Domain
import Foundation
import OSLog

public actor QueryContextUseCase {
    /// Whether the user has explicitly opted in to sending transcript data to MCP providers.
    /// Defaults to `false` — no data leaves the device until the user grants consent.
    public nonisolated let mcpConsentGranted: Bool
    public nonisolated let sensitiveTerms: Set<String>
    private let privacyModeProvider: (any PrivacyModeProvider)?
    /// Updated by the recording session when capture starts/stops.
    public private(set) var isRecording: Bool
    nonisolated private let logger = Logger(subsystem: "app.the-record", category: "QueryContextUseCase")

    /// Updates the recording state so the `.meetings` privacy guard fires correctly.
    /// Call `setRecording(true)` when capture starts and `setRecording(false)` when it ends.
    public func setRecording(_ value: Bool) {
        isRecording = value
    }

    public init(
        mcpConsentGranted: Bool = false,
        privacyModeProvider: (any PrivacyModeProvider)? = nil,
        isRecording: Bool = false,
        sensitiveTerms: Set<String> = []
    ) {
        self.mcpConsentGranted = mcpConsentGranted
        self.privacyModeProvider = privacyModeProvider
        self.isRecording = isRecording
        self.sensitiveTerms = sensitiveTerms
    }

    public func query(text: String, providers: [any ContextProvider]) async -> [Suggestion] {
        guard mcpConsentGranted else { return [] }

        // Privacy mode check — read once to avoid re-entrancy (BIZ-006)
        let currentMode = await privacyModeProvider?.currentPrivacyMode ?? .off
        switch currentMode {
        case .always:
            return []
        case .meetings where isRecording:
            return []
        default:
            break
        }

        // Tier filtering: skip providers that don't support the current mode
        let eligibleProviders = providers.filter { $0.supportedPrivacyTiers.contains(currentMode) }

        let sanitizedText = sanitize(text)
        var allResults: [KnowledgeResult] = []

        await withTaskGroup(of: [KnowledgeResult].self) { group in
            for provider in eligibleProviders {
                group.addTask {
                    do {
                        return try await withTimeout(seconds: 5) {
                            try await provider.query(text: sanitizedText)
                        }
                    } catch {
                        self.logger
                            .warning(
                                // swiftlint:disable:next line_length
                                "Provider \(provider.providerID, privacy: .public) failed: \(String(reflecting: error), privacy: .private)"
                            )
                        return []
                    }
                }
            }
            for await results in group {
                allResults.append(contentsOf: results)
            }
        }

        let suggestions = allResults.map { result in
            Suggestion(
                type: .context,
                title: result.title,
                body: result.body,
                sourceProvider: result.providerID,
                deepLinkURL: result.sourceURL,
                relevanceScore: result.relevanceScore
            )
        }

        let deduplicated = deduplicate(suggestions)
        return deduplicated.sorted { $0.relevanceScore > $1.relevanceScore }
    }

    private nonisolated func sanitize(_ text: String) -> String {
        guard !sensitiveTerms.isEmpty else { return text }
        var result = text
        for term in sensitiveTerms where !term.isEmpty {
            result = result.replacingOccurrences(
                of: term,
                with: "[REDACTED]",
                options: [.caseInsensitive]
            )
        }
        return result
    }

    private nonisolated func deduplicate(_ suggestions: [Suggestion]) -> [Suggestion] {
        var seen: [String: Suggestion] = [:]
        for suggestion in suggestions {
            let key = suggestion.title + "||" + suggestion.sourceProvider.rawValue
            if let existing = seen[key] {
                if suggestion.relevanceScore > existing.relevanceScore {
                    seen[key] = suggestion
                }
            } else {
                seen[key] = suggestion
            }
        }
        return Array(seen.values)
    }
}

// MARK: - Typed timeout error

/// Thrown when a context provider exceeds its query time budget.
/// Distinct from `CancellationError` so callers can tell a provider timeout
/// apart from cooperative task cancellation (DPS-4).
private struct ContextProviderTimeoutError: Error {}

// MARK: - withTimeout

/// withTimeout is intentionally duplicated from Infrastructure/Utilities/Timeout.swift.
/// Business cannot import Infrastructure (architecture boundary). Both versions use
/// typed errors (ContextProviderTimeoutError here, TimeoutError there) appropriate
/// to their context. Consolidation would require a shared utility module — not
/// justified for one 10-line function.
private func withTimeout<T: Sendable>(
    seconds: Double,
    operation: @Sendable @escaping () async throws -> T
) async throws -> T {
    try await withThrowingTaskGroup(of: T.self) { group in
        group.addTask { try await operation() }
        group.addTask {
            try await Task.sleep(for: .seconds(seconds))
            throw ContextProviderTimeoutError()
        }
        defer { group.cancelAll() }
        guard let result = try await group.next() else { throw ContextProviderTimeoutError() }
        return result
    }
}

