    /// is configured. Matching is best-effort: on failure the error is logged
    /// and the unlabeled transcript is returned — a matching outage must never
    /// fail the diarization pass itself.
    private func labelWithEnrolledSpeakers(
        _ transcript: DiarizedTranscript,
        samples: [Float],
    ) async -> DiarizedTranscript {
        guard let matcher else { return transcript }
        do {
            return try await matcher.labelDiarization(transcript, audioSamples: samples)
        } catch {
            logger.error("Speaker matching failed, keeping unlabeled transcript: \(error, privacy: .public)")
            return transcript
        }
    }

