import Domain
import Foundation
import Testing

// MARK: - Fixtures

private func makeMetadata(id: RecordingID) -> RecordingMetadata {
    RecordingMetadata(
        id: id,
        recordedAt: Date(timeIntervalSince1970: 0),
        duration: 12.5,
        fileSize: 4096,
        audioURL: URL(fileURLWithPath: "/tmp/\(id.rawValue).wav"),
        transcriptURL: nil,
        modelId: ModelID("test-model"),
        processingTime: 0.5,
        computeUnit: .cpuOnly,
        wordCount: 10
    )
}

// MARK: - Read-only stub (AC1, AC4)

/// Conforms ONLY to `RecordingReadRepository`. If `RecordingReadRepository`
/// does not exist yet, or if it also requires write methods, this type fails
/// to compile — that is the intended RED failure for AC1/AC4.
private struct ReadOnlyRecordingStore: RecordingReadRepository {
    func getRecording(id: RecordingID) async throws -> StoredRecording {
        StoredRecording(metadata: makeMetadata(id: id))
    }

    func listRecordings(limit: Int?, offset: Int?) async throws -> [RecordingSummary] {
        [RecordingSummary(id: RecordingID("fixed-id"), date: Date(timeIntervalSince1970: 0), duration: 1, wordCount: 3)]
    }

    func totalStorageSize() async throws -> Int64 {
        2048
    }

    func listPendingSessions() async throws -> [RecordingID] {
        [RecordingID("pending-1")]
    }

    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] {
        [makeMetadata(id: RecordingID("meta-1"))]
    }

    func listNeedsRetranscription() async throws -> [RecordingID] { [] }

    func getRecordingForRecovery(id: RecordingID) async throws -> StoredRecording {
        StoredRecording(metadata: makeMetadata(id: id))
    }
}

// MARK: - Write-only stub (AC2, AC5)

/// Conforms ONLY to `RecordingWriteRepository`. If `RecordingWriteRepository`
/// does not exist yet, or if it also requires read methods, this type fails
/// to compile — that is the intended RED failure for AC2/AC5.
private struct WriteOnlyRecordingStore: RecordingWriteRepository {
    func saveRecording(_ file: AudioFile) async throws -> StoredRecording {
        StoredRecording(metadata: makeMetadata(id: file.id))
    }

    func deleteRecording(id: RecordingID) async throws {}

    func markSessionStarted(id: RecordingID, startedAt: Date, audioURL: URL) async throws {}
    func markNeedsRetranscription(id: RecordingID, audioURL: URL) async throws {}
    func clearNeedsRetranscription(id: RecordingID) async throws {}
}

// MARK: - Composition stub (AC3)

/// Conforms only to the two narrower protocols; used to prove
/// `RecordingRepository` is satisfied by their composition (typealias or
/// protocol composition) rather than requiring a separate declaration.
private struct ComposedRecordingStore: RecordingReadRepository, RecordingWriteRepository {
    func getRecording(id: RecordingID) async throws -> StoredRecording {
        StoredRecording(metadata: makeMetadata(id: id))
    }

    func listRecordings(limit: Int?, offset: Int?) async throws -> [RecordingSummary] { [] }
    func totalStorageSize() async throws -> Int64 { 0 }
    func listPendingSessions() async throws -> [RecordingID] { [] }
    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] { [] }
    func listNeedsRetranscription() async throws -> [RecordingID] { [] }

    func saveRecording(_ file: AudioFile) async throws -> StoredRecording {
        StoredRecording(metadata: makeMetadata(id: file.id))
    }

    func deleteRecording(id: RecordingID) async throws {}
    func markSessionStarted(id: RecordingID, startedAt: Date, audioURL: URL) async throws {}
    func markNeedsRetranscription(id: RecordingID, audioURL: URL) async throws {}
    func clearNeedsRetranscription(id: RecordingID) async throws {}
}

// MARK: - Tests

@Suite("task-002 — RecordingRepository read/write split")
struct RecordingRepositoryProtocolTests {
    // AC1: RecordingReadRepository protocol exists declaring read methods
    // previously on RecordingRepository.
    @Test
    func ac1_recordingReadRepositoryDeclaresReadMethods() async throws {
        let store: any RecordingReadRepository = ReadOnlyRecordingStore()

        let summaries = try await store.listRecordings(limit: nil, offset: nil)
        #expect(summaries.count == 1)
        #expect(summaries.first?.wordCount == 3)

        let pending = try await store.listPendingSessions()
        #expect(pending == [RecordingID("pending-1")])

        let size = try await store.totalStorageSize()
        #expect(size == 2048)
    }

    // AC2: RecordingWriteRepository protocol exists declaring write methods
    // previously on RecordingRepository.
    @Test
    func ac2_recordingWriteRepositoryDeclaresWriteMethods() async throws {
        let store: any RecordingWriteRepository = WriteOnlyRecordingStore()

        let file = AudioFile(
            id: RecordingID("saved-1"),
            url: URL(fileURLWithPath: "/tmp/saved-1.wav"),
            recordedAt: Date(timeIntervalSince1970: 0),
            duration: 5,
            fileSize: 1024,
            configuration: AudioConfiguration(),
            sampleCount: 100
        )

        let stored = try await store.saveRecording(file)
        #expect(stored.metadata.id == RecordingID("saved-1"))

        try await store.deleteRecording(id: RecordingID("saved-1"))
        try await store.markSessionStarted(
            id: RecordingID("saved-1"),
            startedAt: Date(timeIntervalSince1970: 0),
            audioURL: URL(fileURLWithPath: "/tmp/saved-1.wav")
        )
    }

    // AC3: RecordingRepository is reduced to a typealias/composition of
    // RecordingReadRepository & RecordingWriteRepository, so a type
    // conforming to both narrower protocols also satisfies
    // RecordingRepository without any additional declarations.
    @Test
    func ac3_recordingRepositoryIsComposedFromReadAndWrite() async throws {
        let store: any RecordingRepository = ComposedRecordingStore()

        let file = AudioFile(
            id: RecordingID("composed-1"),
            url: URL(fileURLWithPath: "/tmp/composed-1.wav"),
            recordedAt: Date(timeIntervalSince1970: 0),
            duration: 3,
            fileSize: 512,
            configuration: AudioConfiguration(),
            sampleCount: 50
        )

        let stored = try await store.saveRecording(file)
        #expect(stored.metadata.id == RecordingID("composed-1"))

        let fetched = try await store.getRecording(id: RecordingID("composed-1"))
        #expect(fetched.metadata.id == RecordingID("composed-1"))
    }

    // AC4: A test-double conforming ONLY to RecordingReadRepository compiles
    // without implementing write methods.
    @Test
    func ac4_readOnlyStoreCompilesWithoutWriteMethods() async throws {
        let store = ReadOnlyRecordingStore()
        let recording = try await store.getRecording(id: RecordingID("r-1"))
        #expect(recording.metadata.id == RecordingID("r-1"))
    }

    // AC5: A test-double conforming ONLY to RecordingWriteRepository compiles
    // without implementing read methods.
    @Test
    func ac5_writeOnlyStoreCompilesWithoutReadMethods() async throws {
        let store = WriteOnlyRecordingStore()
        let file = AudioFile(
            id: RecordingID("w-1"),
            url: URL(fileURLWithPath: "/tmp/w-1.wav"),
            recordedAt: Date(timeIntervalSince1970: 0),
            duration: 1,
            fileSize: 10,
            configuration: AudioConfiguration(),
            sampleCount: 1
        )
        let stored = try await store.saveRecording(file)
        #expect(stored.metadata.id == RecordingID("w-1"))
    }
}

