@testable import Business
import Domain
import Testing

// MARK: - Fakes

/// Minimal fake ``SummarizationEngine`` that returns a fixed summary.
private actor FakeSummarizationEngine: SummarizationEngine {
    private(set) var loadModelCalled = false
    private let stubSummary: MeetingSummary

    init(stubSummary: MeetingSummary) {
        self.stubSummary = stubSummary
    }

    func loadModel(_: SummaryConfig) async throws {
        loadModelCalled = true
    }

    func summarize(
        transcript _: String, speakers _: [String], meetingType _: MeetingType
    ) async throws -> MeetingSummary {
        stubSummary
    }

    func isReady() async -> Bool {
        true
    }
}

/// Fake write-side repository that captures every saved summary so tests can
/// assert on call count and payload without a real persistence backend.
///
/// This type conforms to `SummaryWriteRepository`, which does not exist yet
/// in `Record-CrossPlatform-Foundation`'s `Domain` module — this file will
/// fail to compile until that protocol is added (task-005 GREEN phase).
private actor FakeSummaryWriteRepository: SummaryWriteRepository {
    private(set) var savedSummaries: [RecordingID: MeetingSummary] = [:]
    private(set) var saveCallCount = 0

    func saveSummary(for recordingId: RecordingID, summary: MeetingSummary) async throws {
        saveCallCount += 1
        savedSummaries[recordingId] = summary
    }
}

// MARK: - Fixtures

private func makeTranscript() -> DiarizedTranscript {
    let segments: [DiarizedSegment] = [
        DiarizedSegment(
            text: "Hello everyone",
            speakerId: SpeakerID("speaker-0"),
            startTime: 0.0,
            endTime: 5.0,
            confidence: 0.9
        ),
    ]
    return DiarizedTranscript(segments: segments, speakerCount: 1, processingTime: 1.0)
}

private func makeExpectedSummary() -> MeetingSummary {
    MeetingSummary(
        summary: "A productive meeting",
        decisions: ["Ship task-005"],
        actionItems: [],
        topics: ["Architecture"],
        openQuestions: [],
        generatedAt: Date(timeIntervalSince1970: 1_000_000),
        modelId: ModelID("test-model"),
        processingTime: 1.0
    )
}

// MARK: - Suite

@Suite("SummarizeMeetingUseCase — SummaryWriteRepository")
struct SummarizeMeetingUseCaseTests {
    // AC1: SummaryWriteRepository protocol exists declaring a save/write method.
    @Test("SummaryWriteRepository declares saveSummary(for:summary:) and a fake can conform to it")
    func summaryWriteRepositoryProtocolDeclaresSaveMethod() async throws {
        let fake = FakeSummaryWriteRepository()
        let recordingId = RecordingID("rec-protocol-check")
        let summary = makeExpectedSummary()

        try await fake.saveSummary(for: recordingId, summary: summary)

        let count = await fake.saveCallCount
        #expect(count == 1, "conforming fake must be able to call saveSummary exactly once")
        let saved = await fake.savedSummaries[recordingId]
        #expect(saved == summary, "the exact summary passed to saveSummary must be retrievable")
    }

    // AC2: SummarizeMeetingUseCase.swift references SummaryWriteRepository via
    // its `storage` dependency and initializer, and the file compiles.
    @Test("SummarizeMeetingUseCase accepts a SummaryWriteRepository via its storage initializer parameter")
    func useCaseInitializerAcceptsSummaryWriteRepository() async throws {
        let engine = FakeSummarizationEngine(stubSummary: makeExpectedSummary())
        let storage: any SummaryWriteRepository = FakeSummaryWriteRepository()

        let useCase = SummarizeMeetingUseCase(summarization: engine, storage: storage)

        let result = try await useCase.summarize(
            recordingId: RecordingID("rec-init-check"),
            transcript: makeTranscript()
        )

        #expect(result == makeExpectedSummary(), "use case must still return the engine's summary unchanged")
    }

    // AC3: exercises the summary-write path via a fake SummaryWriteRepository,
    // asserting execute(...) calls save exactly once with the expected summary.
    @Test("summarize calls storage.saveSummary exactly once with the expected summary")
    func summarizeCallsSaveSummaryExactlyOnceWithExpectedSummary() async throws {
        let expectedSummary = makeExpectedSummary()
        let engine = FakeSummarizationEngine(stubSummary: expectedSummary)
        let fakeStorage = FakeSummaryWriteRepository()
        let recordingId = RecordingID("rec-write-path")

        let useCase = SummarizeMeetingUseCase(summarization: engine, storage: fakeStorage)
        _ = try await useCase.summarize(recordingId: recordingId, transcript: makeTranscript())

        let callCount = await fakeStorage.saveCallCount
        #expect(callCount == 1, "saveSummary must be called exactly once per summarize invocation")

        let saved = await fakeStorage.savedSummaries[recordingId]
        #expect(saved == expectedSummary, "the saved summary must match exactly what the engine produced")
    }
}

