// MARK: - Fakes

/// Fake diarization engine that returns a single fixed speaker segment
/// spanning the whole recording, recording lifecycle call counts so tests
/// can assert `prepare()`/`diarize` were exercised.
private actor FakeDiarizationEngine: DiarizationEngine {
    private(set) var prepareCallCount = 0
    private(set) var diarizeCallCount = 0
    private var ready = false
    private let segments: [SpeakerSegment]

    init(segments: [SpeakerSegment]) {
        self.segments = segments
    }

    func prepare() async throws {
        prepareCallCount += 1
        ready = true
    }

    func diarize(samples: [Float], sampleRate: Int) async throws -> [SpeakerSegment] {
        diarizeCallCount += 1
        return segments
    }

    func isReady() async -> Bool {
        ready
    }
}

