import Foundation
@testable import Business
import Domain
import Testing

// MARK: - Fakes

/// Read-only repository fake. Conforms to `RecordingReadRepository` ONLY —
/// constructing `CleanupTranscriptionUseCase` with this fake is the compile-time
/// proof that the use case is typed against the split read protocol, not the
/// combined `RecordingRepository` (task-009 AC, ports the App-side split).
private actor FakeReadRepository: RecordingReadRepository {
    private let stored: StoredRecording

    init(stored: StoredRecording) {
        self.stored = stored
    }

    func listRecordings(limit _: Int?, offset _: Int?) async throws -> [RecordingSummary] { [] }

    func getRecording(id _: RecordingID) async throws -> StoredRecording { stored }

    func totalStorageSize() async throws -> Int64 { 0 }

    func listPendingSessions() async throws -> [RecordingID] { [] }

    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] { [] }

    func listNeedsRetranscription() async throws -> [RecordingID] { [] }
}

private actor FakeTranscriptReader: TranscriptReadRepository {
    private let draft: String?

    init(draft: String?) {
        self.draft = draft
    }

    func searchTranscripts(query _: String, limit _: Int?, offset _: Int?) async throws -> [RecordingSummary] { [] }

    func getTranscriptDraft(for _: RecordingID) async throws -> String? { draft }
}

private struct TransientStorageFailure: Error {}

/// Write-side fake that can be configured to throw on `saveDraftTranscript`,
/// reproducing the #326 scenario: a transient draft-save failure must not
/// discard the successfully computed cleanup transcript.
private actor FakeTranscriptWriter: TranscriptWriteRepository {
    private let draftSaveError: Error?
    private(set) var savedDrafts: [String] = []
    private(set) var updateTranscriptCallCount = 0
    private(set) var lastUpdatedTranscript: TranscriptionResult?

    init(draftSaveError: Error? = nil) {
        self.draftSaveError = draftSaveError
    }

    func updateTranscript(id _: RecordingID, transcript: TranscriptionResult) async throws {
        updateTranscriptCallCount += 1
        lastUpdatedTranscript = transcript
    }

    func saveDraftTranscript(draftText: String, for _: RecordingID) async throws {
        if let draftSaveError {
            throw draftSaveError
        }
        savedDrafts.append(draftText)
    }
}

private actor FakeTranscriptionEngine: TranscriptionEngine {
    func loadModel(_: ModelID) async throws {}

    func transcribe(samples _: [Float], context _: TranscriptionContext) async throws -> TranscriptionSegment {
        TranscriptionSegment(
            id: SegmentID(UUID().uuidString),
            text: "cleaned text",
            startTime: 0,
            endTime: 1,
            confidence: 0.95,
            isFinal: true,
            sequenceNumber: 0
        )
    }

    func isReady() async -> Bool { true }

    func warmUp() async throws {}
}

private struct FakeSampleLoader: AudioSampleLoader {
    func loadSamples(from _: URL) async throws -> [Float] {
        [Float](repeating: 0, count: 16000)
    }
}

// MARK: - Fixtures

private func makeStoredRecording(id: RecordingID, liveText: String?) -> StoredRecording {
    let metadata = RecordingMetadata(
        id: id,
        recordedAt: Date(timeIntervalSince1970: 1_000_000),
        duration: 1,
        fileSize: 1024,
        audioURL: URL(fileURLWithPath: "/fake/audio.wav"),
        transcriptURL: nil,
        modelId: ModelID("fake-model"),
        processingTime: 0,
        computeUnit: .cpuOnly,
        wordCount: 2
    )
    let transcript = liveText.map { text in
        TranscriptionResult(
            segments: [],
            fullText: text,
            processingTime: 0.1,
            modelId: ModelID("fake-model"),
            recordedAt: Date(timeIntervalSince1970: 1_000_000),
            computeUnit: .cpuOnly,
            passType: .live
        )
    }
    return StoredRecording(metadata: metadata, transcript: transcript)
}

// MARK: - Tests

@Suite("CleanupTranscriptionUseCase #326 fix")
struct CleanupTranscriptionUseCaseFixTests {
    private let recordingId = RecordingID("rec-326")

    private func makeUseCase(
        liveText: String? = "live words",
        existingDraft: String? = nil,
        writer: FakeTranscriptWriter
    ) -> CleanupTranscriptionUseCase {
        CleanupTranscriptionUseCase(
            transcription: FakeTranscriptionEngine(),
            sampleLoader: FakeSampleLoader(),
            reader: FakeReadRepository(stored: makeStoredRecording(id: recordingId, liveText: liveText)),
            transcriptReader: FakeTranscriptReader(draft: existingDraft),
            writer: writer
        )
    }

    @Test("transient draft-save failure is non-fatal: cleanup result is still persisted (#326)")
    func draftSaveFailureDoesNotDiscardCleanupResult() async throws {
        let writer = FakeTranscriptWriter(draftSaveError: TransientStorageFailure())
        let useCase = makeUseCase(writer: writer)

        let result = try await useCase.transcribeCleanupPass(
            recordingId: recordingId,
            modelId: ModelID("cleanup-model")
        )

        #expect(result.passType == .cleanup)
        #expect(await writer.updateTranscriptCallCount == 1)
        #expect(await writer.lastUpdatedTranscript?.fullText == "cleaned text")
    }

    @Test("live transcript is drafted before overwrite when no draft exists")
    func draftSavedWhenNoneExists() async throws {
        let writer = FakeTranscriptWriter()
        let useCase = makeUseCase(writer: writer)

        _ = try await useCase.transcribeCleanupPass(
            recordingId: recordingId,
            modelId: ModelID("cleanup-model")
        )

        #expect(await writer.savedDrafts == ["live words"])
        #expect(await writer.updateTranscriptCallCount == 1)
    }

    @Test("existing draft is never overwritten (idempotent guard)")
    func existingDraftIsPreserved() async throws {
        let writer = FakeTranscriptWriter()
        let useCase = makeUseCase(existingDraft: "already drafted", writer: writer)

        _ = try await useCase.transcribeCleanupPass(
            recordingId: recordingId,
            modelId: ModelID("cleanup-model")
        )

        #expect(await writer.savedDrafts.isEmpty)
        #expect(await writer.updateTranscriptCallCount == 1)
    }
}

import Foundation
@testable import Business
import Domain
import Testing

// MARK: - Fakes

/// Read repository returning a fixed stored recording, or throwing when
/// configured with an error.
private actor FakeDiarizationReadRepository: RecordingReadRepository {
    private let stored: StoredRecording?
    private let error: Error?

    init(stored: StoredRecording? = nil, error: Error? = nil) {
        self.stored = stored
        self.error = error
    }

    func getRecording(id: RecordingID) async throws -> StoredRecording {
        if let error { throw error }
        guard let stored else { throw StorageError.recordingNotFound(id: id) }
        return stored
    }

    func listRecordings(limit _: Int?, offset _: Int?) async throws -> [RecordingSummary] { [] }
    func totalStorageSize() async throws -> Int64 { 0 }
    func listPendingSessions() async throws -> [RecordingID] { [] }
    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] { [] }
    func listNeedsRetranscription() async throws -> [RecordingID] { [] }
}

private actor FakeDiarizationWriter: DiarizationWriteRepository {
    private(set) var attachDiarizationCalled = false
    private(set) var lastAttached: DiarizedTranscript?

    func attachDiarization(id _: RecordingID, diarization: DiarizedTranscript) async throws {
        attachDiarizationCalled = true
        lastAttached = diarization
    }
}

/// Spy engine modelling the "not ready but prepare() succeeds" state that a
/// simple stub cannot express — mirrors the App-side BM-038 spy.
private actor SpyDiarizationEngine: DiarizationEngine {
    private var ready: Bool
    private let prepareError: Error?
    private let segments: [SpeakerSegment]
    private let diarizeError: Error?

    private(set) var prepareCalled = false
    private(set) var diarizeCalled = false

    init(
        ready: Bool = true,
        prepareError: Error? = nil,
        segments: [SpeakerSegment] = [],
        diarizeError: Error? = nil
    ) {
        self.ready = ready
        self.prepareError = prepareError
        self.segments = segments
        self.diarizeError = diarizeError
    }

    func isReady() async -> Bool { ready }

    func prepare() async throws {
        prepareCalled = true
        if let prepareError { throw prepareError }
        ready = true
    }

    func diarize(samples _: [Float], sampleRate _: Int) async throws -> [SpeakerSegment] {
        diarizeCalled = true
        if let diarizeError { throw diarizeError }
        return segments
    }
}

private struct StubSampleLoader: AudioSampleLoader {
    func loadSamples(from _: URL) async throws -> [Float] {
        [Float](repeating: 0, count: 16000)
    }
}

// MARK: - Fixtures

private func makeStoredRecording(id: RecordingID = RecordingID("recording-001")) -> StoredRecording {
    StoredRecording(metadata: RecordingMetadata(
        id: id,
        recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
        duration: 120.0,
        fileSize: 2_097_152,
        audioURL: URL(fileURLWithPath: "/recordings/test-audio.wav"),
        transcriptURL: nil,
        modelId: ModelID("openai_whisper-tiny"),
        processingTime: 2.0,
        computeUnit: .cpuOnly,
        wordCount: 0
    ))
}

private func makeSegment(_ id: String, text: String, start: TimeInterval, end: TimeInterval, seq: Int) -> TranscriptionSegment {
    TranscriptionSegment(id: SegmentID(id), text: text, startTime: start, endTime: end, confidence: 0.9, isFinal: true, sequenceNumber: seq)
}

private func makeTranscription(segments: [TranscriptionSegment]) -> TranscriptionResult {
    TranscriptionResult(
        segments: segments,
        fullText: segments.map(\.text).joined(separator: " "),
        processingTime: 1.0,
        modelId: ModelID("openai_whisper-tiny"),
        recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
        computeUnit: .cpuOnly,
        passType: .cleanup
    )
}

/// Three transcript segments across two speaker ranges:
///   seg-0 (0–5 s):   overlap speaker-0 = 5.0, speaker-1 = 0.0 → speaker-0
///   seg-1 (5–10 s):  overlap speaker-0 = 2.0, speaker-1 = 3.0 → speaker-1
///   seg-2 (10–15 s): overlap speaker-0 = 0.0, speaker-1 = 5.0 → speaker-1
private func makeThreeSegmentTranscription() -> TranscriptionResult {
    makeTranscription(segments: [
        makeSegment("seg-0", text: "Hello world", start: 0, end: 5, seq: 0),
        makeSegment("seg-1", text: "How are you", start: 5, end: 10, seq: 1),
        makeSegment("seg-2", text: "I am fine", start: 10, end: 15, seq: 2),
    ])
}

/// speaker-0 covers 0–7 s, speaker-1 covers 7–15 s.
private func makeTwoSpeakerSegments() -> [SpeakerSegment] {
    [
        SpeakerSegment(speakerId: SpeakerID("speaker-0"), startTime: 0, endTime: 7, confidence: 0.9),
        SpeakerSegment(speakerId: SpeakerID("speaker-1"), startTime: 7, endTime: 15, confidence: 0.85),
    ]
}

private func makeUseCase(
    engine: SpyDiarizationEngine,
    reader: FakeDiarizationReadRepository,
    writer: FakeDiarizationWriter = FakeDiarizationWriter()
) -> DiarizeMeetingUseCase {
    DiarizeMeetingUseCase(
        diarization: engine,
        sampleLoader: StubSampleLoader(),
        reader: reader,
        writer: writer
    )
}

// MARK: - Suite (App-side parity, task-012)

@Suite("task-012 — DiarizeMeetingUseCase App-side behavioral parity")
struct DiarizeMeetingUseCaseBehaviorTests {
    @Test("happy path assigns correct speakers to 3 transcript segments across 2 speaker ranges")
    func happyPathAssignsCorrectSpeakers() async throws {
        let engine = SpyDiarizationEngine(segments: makeTwoSpeakerSegments())
        let useCase = makeUseCase(engine: engine, reader: FakeDiarizationReadRepository(stored: makeStoredRecording()))

        let result = try await useCase.diarize(
            recordingId: RecordingID("recording-001"),
            transcription: makeThreeSegmentTranscription()
        )

        #expect(result.segments.count == 3)
        #expect(result.segments[0].speakerId == SpeakerID("speaker-0"))
        #expect(result.segments[1].speakerId == SpeakerID("speaker-1"))
        #expect(result.segments[2].speakerId == SpeakerID("speaker-1"))
        #expect(result.speakerCount == 2)
    }

    @Test("storage failure propagates without being swallowed")
    func storageFailurePropagates() async throws {
        let useCase = makeUseCase(engine: SpyDiarizationEngine(), reader: FakeDiarizationReadRepository())

        await #expect(throws: (any Error).self) {
            _ = try await useCase.diarize(
                recordingId: RecordingID("recording-001"),
                transcription: makeThreeSegmentTranscription()
            )
        }
    }

    @Test("diarization failure propagates without being swallowed")
    func diarizationFailurePropagates() async throws {
        struct EngineError: Error {}
        let engine = SpyDiarizationEngine(diarizeError: EngineError())
        let useCase = makeUseCase(engine: engine, reader: FakeDiarizationReadRepository(stored: makeStoredRecording()))

        await #expect(throws: (any Error).self) {
            _ = try await useCase.diarize(
                recordingId: RecordingID("recording-001"),
                transcription: makeThreeSegmentTranscription()
            )
        }
    }

    @Test("segment outside all speaker ranges is assigned Unknown")
    func segmentWithNoOverlapGetsUnknown() async throws {
        let engine = SpyDiarizationEngine(segments: makeTwoSpeakerSegments())
        let useCase = makeUseCase(engine: engine, reader: FakeDiarizationReadRepository(stored: makeStoredRecording()))

        // seg-gap (20–25 s) has no overlap with the speaker segments (0–15 s).
        let transcription = makeTranscription(segments: [
            makeSegment("seg-0", text: "Hello", start: 0, end: 5, seq: 0),
            makeSegment("seg-gap", text: "Gap segment", start: 20, end: 25, seq: 1),
        ])

        let result = try await useCase.diarize(recordingId: RecordingID("recording-001"), transcription: transcription)

        #expect(result.segments.count == 2)
        #expect(result.segments[0].speakerId == SpeakerID("speaker-0"))
        #expect(result.segments[1].speakerId == SpeakerID.unknown)
