// MARK: - Fakes

/// Fake diarization engine that returns a single fixed speaker segment
/// spanning the whole recording, recording lifecycle call counts so tests
/// can assert `prepare()`/`diarize` were exercised.
private actor FakeDiarizationEngine: DiarizationEngine {
    private(set) var prepareCallCount = 0
    private(set) var diarizeCallCount = 0
    private var ready = false
    private let segments: [SpeakerSegment]

    init(segments: [SpeakerSegment]) {
        self.segments = segments
    }

    func prepare() async throws {
        prepareCallCount += 1
        ready = true
    }

    func diarize(samples: [Float], sampleRate: Int) async throws -> [SpeakerSegment] {
        diarizeCallCount += 1
        return segments
    }

    func isReady() async -> Bool {
        ready
    }
}

/// Fake sample loader that returns a fixed PCM buffer regardless of the
/// requested URL, recording invocation count.
private actor FakeAudioSampleLoader: AudioSampleLoader {
    private(set) var loadSamplesCallCount = 0
    private let samples: [Float]

    init(samples: [Float]) {
        self.samples = samples
    }

    func loadSamples(from url: URL) async throws -> [Float] {
        loadSamplesCallCount += 1
        return samples
    }
}

/// Fake read-side repository backing `DiarizeMeetingUseCase`, conforming to
/// `RecordingReadRepository` per the fix under test (task-007).
private actor FakeRecordingReadRepository: RecordingReadRepository {
    private(set) var getRecordingCallCount = 0
    private let storedRecording: StoredRecording

    init(storedRecording: StoredRecording) {
        self.storedRecording = storedRecording
    }

    func getRecording(id: RecordingID) async throws -> StoredRecording {
        getRecordingCallCount += 1
        return storedRecording
    }

    func listRecordings(limit: Int?, offset: Int?) async throws -> [RecordingSummary] {
        []
    }

    func totalStorageSize() async throws -> Int64 {
        0
    }

    func listPendingSessions() async throws -> [RecordingID] {
        []
    }

    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] {
        []
    }

    func listNeedsRetranscription() async throws -> [RecordingID] {
        []
    }
}

/// Fake write-side repository backing `DiarizeMeetingUseCase`'s persistence
/// step. Conforms to `DiarizationWriteRepository` — the type name
/// `DiarizeMeetingUseCase.swift` is expected to reference once task-007's
/// compile-error fix lands. Until then this fails to compile with
/// "cannot find type 'DiarizationWriteRepository' in scope", which is the
/// RED failure this test file proves.
private actor FakeDiarizationWriteRepository: DiarizationWriteRepository {
    private(set) var attachDiarizationCallCount = 0
    private(set) var lastAttachedId: RecordingID?
    private(set) var lastAttachedTranscript: DiarizedTranscript?

    func attachDiarization(id: RecordingID, diarization: DiarizedTranscript) async throws {
        attachDiarizationCallCount += 1
        lastAttachedId = id
        lastAttachedTranscript = diarization
    }
}

