/// Polls until `condition` is true or ~2s elapse, yielding between checks.
private func waitUntil(_ condition: @Sendable () -> Bool) async {
    for _ in 0..<200 {
        if condition() { return }
        try? await Task.sleep(nanoseconds: 10_000_000)
    }
}

// MARK: - Tests

@Suite("task-011 — PipelineCoordinator onStateChange SSOT callback")
struct PipelineCoordinatorStateChangeTests {
    @Test("cleanup transitions emit consolidated (CleanupState, PipelineState) pairs in order")
    func cleanupTransitionsEmitConsolidatedPairs() async throws {
        let recorder = StatePairRecorder()
        let coordinator = makeCoordinator()
        await coordinator.setOnStateChange { cleanup, pipeline in
            recorder.append(cleanup, pipeline)
        }

        _ = await coordinator.runCleanupPass(recordingId: RecordingID("rec-1"))

        let pairs = recorder.pairs
        #expect(pairs.count == 2, "expected .running then .idle cleanup transitions, got \(pairs.count) emissions")
        #expect(pairs.first?.0.isRunning == true, "first emission must carry CleanupState.running")
        if case .idle = pairs.first?.1 {} else {
            Issue.record("first emission must carry the current PipelineState (.idle)")
        }
        if case .idle = pairs.last?.0 {} else {
            Issue.record("failed cleanup must emit CleanupState.idle as the final transition")
        }
    }

    @Test("pipeline transitions emit consolidated pairs carrying the current cleanup state")
    func pipelineTransitionsEmitConsolidatedPairs() async throws {
        let recorder = StatePairRecorder()
        let coordinator = makeCoordinator()
        await coordinator.setOnStateChange { cleanup, pipeline in
            recorder.append(cleanup, pipeline)
        }

        await coordinator.startPipeline(for: RecordingID("rec-2"), liveTranscription: makeTranscriptionResult())
        await waitUntil { recorder.pairs.count >= 2 }

        let pairs = recorder.pairs
        #expect(pairs.count >= 2, "expected .diarizing then .failed pipeline transitions")
        #expect(pairs.first?.1.isDiarizing == true, "first emission must carry PipelineState.diarizing")
        if case .failed = pairs.last?.1 {} else {
            Issue.record("throwing diarization must emit PipelineState.failed as the final transition")
        }
        if case .idle = pairs.last?.0 {} else {
            Issue.record("pipeline transitions must carry the current CleanupState (.idle)")
        }
    }

    @Test("cancelAll emits a single consolidated (.idle, .idle) pair")
    func cancelAllEmitsIdlePair() async throws {
        let recorder = StatePairRecorder()
        let coordinator = makeCoordinator()
        await coordinator.setOnStateChange { cleanup, pipeline in
            recorder.append(cleanup, pipeline)
        }

        await coordinator.cancelAll()

        let pairs = recorder.pairs
        #expect(pairs.count == 1, "cancelAll must emit exactly one consolidated pair")
        if case .some((.idle, .idle)) = pairs.first {} else {
            Issue.record("cancelAll must emit (.idle, .idle)")
        }
    }
}

