>>>>>>> origin/main
    func importMetadata(_: RecordingMetadata) async throws {}

    func getRecording(id: RecordingID) async throws -> StoredRecording {
        getRecordingCalledWith = id
        guard let recording = recordingToReturn else {
            throw StorageError.recordingNotFound(id: id)
        }
        return recording
    }

    func getRecordingForRecovery(id: RecordingID) async throws -> StoredRecording {
        try await getRecording(id: id)
    }

    func listRecordings(limit: Int? = nil, offset: Int? = nil) async throws -> [RecordingSummary] {
        []
    }

    func listPendingSessions() async throws -> [RecordingID] {
