        getSummaryCalledWith = recordingId
        return summaryToReturn
    }

    func getNotes(meetingId _: RecordingID) async throws -> String {
        if let error = notesErrorToThrow { throw error }
        return ""
    }

    func deleteRecording(id _: RecordingID) async throws {
