    func searchTranscripts(query _: String, limit: Int? = nil, offset: Int? = nil) async throws -> [RecordingSummary] {
        fatalError("unused in MeetingDetailViewModel tests")
    }

    func totalStorageSize() async throws -> Int64 {
        fatalError("unused in MeetingDetailViewModel tests")
    }

    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] {
        fatalError("unused in MeetingDetailViewModel tests")
    }

    func saveNotes(meetingId _: RecordingID, text: String) async throws {
        saveNotesCallCount += 1
        lastSavedText = text
    }

    // MARK: Test helpers

    func seed(recording: StoredRecording) {
        recordingToReturn = recording
    }

    func seed(summary: MeetingSummary?) {
        summaryToReturn = summary
    }

    func seed(notesError: any Error) {
        notesErrorToThrow = notesError
    }
}

