/// Abstracts the meeting summarisation backend (e.g. MLX LLM) so the domain
/// layer has no compile-time dependency on any inference framework.
public protocol SummarizationEngine: Sendable {
    /// Loads the model described by `config` and prepares it for inference.
    /// - Throws: ``SummarizationError`` if the model cannot be loaded.
    func loadModel(_ config: SummaryConfig) async throws

    /// Generates a structured meeting summary from transcript text, speaker list,
    /// and meeting type (which selects the prompt template).
    func summarize(
        transcript: String, speakers: [String], meetingType: MeetingType
    ) async throws -> MeetingSummary

    /// Returns `true` when the model is loaded and ready for inference.
    func isReady() async -> Bool

    /// Generates text from a raw prompt, bypassing summarization formatting.
    func generate(prompt: String) async throws -> String
}

public extension SummarizationEngine {
    func summarize(transcript: String, speakers: [String]) async throws -> MeetingSummary {
        try await summarize(
            transcript: transcript, speakers: speakers,
            meetingType: SummaryConfig.default.meetingType
        )
    }
