#!/usr/bin/env python3
"""PreToolUse Bash hook: block git write operations on the main branch."""

import json
import re
import subprocess
import sys

GIT_WRITE_PATTERN = re.compile(
    r"\bgit\s+(commit|push|merge|rebase|reset\s+--hard|branch\s+-[Dd])\b"
)


def main() -> None:
    try:
        raw = sys.stdin.read()
        cmd = json.loads(raw).get("command", "") if raw.strip() else ""
    except Exception:
        sys.exit(0)

    if not GIT_WRITE_PATTERN.search(cmd):
        sys.exit(0)

    try:
        branch = subprocess.check_output(
            ["git", "rev-parse", "--abbrev-ref", "HEAD"], text=True
        ).strip()
        if branch == "main":
            print(
                "GUARD: Direct git write operations on 'main' are blocked.\n"
                "Switch to a feature branch before committing or pushing.",
                file=sys.stderr,
            )
            sys.exit(1)
    except Exception as exc:
        print(
            f"WARNING: guard-main-commit.py crashed ({exc}). Failing open.",
            file=sys.stderr,
        )

    sys.exit(0)


if __name__ == "__main__":
    main()
